def G(t):
    R=[("Import memory to Gemini","Імпорт мемморі ту Джеміні"),("Gemini Live","Джеміні Лайв"),("Gemini Notebook","Джеміні Ноутбук"),("Google AI Plus","Гугл Ей-Ай Плас"),("Google AI Pro","Гугл Ей-Ай Про"),("Google AI Ultra","Гугл Ей-Ай Ультра"),
       ("Google AI","Гугл Ей-Ай"),("AI Plus","Ей-Ай Плас"),("AI Pro","Ей-Ай Про"),("Google One","Гугл Ван"),("Google Flow","Гугл Флоу"),("Google Workspace","Гугл Воркспейс"),
       ("gemini.google.com","джеміні крапка гугл крапка ком"),("gemini.google/desktop","джеміні крапка гугл слеш десктоп"),("Gemini","Джеміні"),
       ("Nano Banana Pro","Нано Банана Про"),("Nano Banana","Нано Банана"),("Deep Research","Діп Ресьорч"),("Canvas","Кенвас"),("Hydrogen","Гайдроджен"),("Neon","Неон"),("Carbon","Карбон"),("Auto","Авто"),
       ("Manage subscription","Менедж сабскрипшн"),("Settings","Сеттінгз"),("Images","Імеджіз"),
       ("ChatGPT Plus","Чат Джі-Пі-Ті Плас"),("ChatGPT","Чат Джі-Пі-Ті"),("Claude Pro","Клод Про"),("Claude","Клод"),("Google Play","Гугл Плей"),("App Store","Еп Стор"),
       ("Gmail","Джимейл"),("Google","Гугл"),("Windows","Віндоус"),("Mac","Мак"),("Android","Андроїд"),("iPhone","Айфон"),("iOS","Ай-Оу-Ес"),("VPN","ві-пі-ен"),
       ("Alt","Альт"),("Space","Спейс"),("Excel","Ексель"),("Word","Ворд"),("PDF","пі-ді-еф"),("zip","зіп"),("Ultra","Ультра"),("Plus","Плас"),("Free","Фрі"),("Pro","Про"),("SMS","есемес")]
    t=t.replace("@Gmail","собачка Джимейл")
    for a,b in R: t=re.sub(r"(?<![\w-])"+re.escape(a)+r"(?![\w])", b, t)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("на ШІ","на штучний інтелект"),("у ШІ","у штучний інтелект")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

